using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class Revision26Tests {
 static string dir;static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static void Check(bool v,string m){if(!v)throw new Exception(m);}static void Snap(Form f,string name){using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,name+".png"));}}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS: presets and custom paper, all four margins, units and languages, one label per page, copies only in printer settings, separate transparent Word SVG parts, Windows print preview pipeline, logo and signature.");}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
 static void Run(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new MainForm(Path.Combine(dir,"no-startup.xml"))){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();Check(f.Text.StartsWith("ND LabelDesigner — prelease  |  "),"name");var paper=(ComboBox)Field(f,"paperPreset");var nums=(System.Collections.Generic.Dictionary<string,NumericUpDown>)Field(f,"nums");Check(!nums.ContainsKey("Copies")&&!nums.ContainsKey("GapX"),"removed copy controls");
  for(int i=1;i<7;i++){paper.SelectedIndex=i;var s=(LabelSettings)Call(f,"Read");Check(s.UsePaper&&!s.Sheet&&s.Copies==1,"single label");Check(s.PageWidth==PaperOptions.Width[i]&&s.PageHeight==PaperOptions.Height[i]&&!nums["PageWidth"].Enabled,"fixed dimensions");Engine.Validate(s);}
  paper.SelectedIndex=7;nums["PageWidth"].Value=180;nums["PageHeight"].Value=110;nums["MarginX"].Value=12;nums["MarginRight"].Value=18;nums["MarginY"].Value=9;nums["MarginBottom"].Value=14;((ComboBox)Field(f,"units")).SelectedItem="cm";var custom=(LabelSettings)Call(f,"Read");Check(custom.PageWidth==180&&custom.MarginRight==18&&custom.MarginBottom==14,"custom dimensions and margins persist in cm");Engine.Save(Path.Combine(dir,"custom.xml"),custom);Check(Engine.Load(Path.Combine(dir,"custom.xml")).MarginRight==18,"XML persistence");
  custom.Texts.Add(new TextItem{Text="Cena: 12,90 €",X=3,Y=39,Width=54,Height=5,Size=8});custom.Symbols.Add(new SymbolItem{X=45,Y=3,Width=10,Height=10*DepositArt.Aspect});Engine.Docx(Path.Combine(dir,"parts.docx"),custom);Engine.Pdf(Path.Combine(dir,"paper.pdf"),custom);var parts=WordParts.Create(custom);Check(parts.Count==4,"each text barcode symbol separate");foreach(var part in parts)Check(!part.Svg.Contains("fill=\"white\"")&&part.Bounds.Width>0,"transparent parts");
  using(var doc=new LabelPrintDocument(custom)){doc.PrinterSettings.Copies=3;Check(doc.PageCount==1&&doc.Capacity==1,"copies not expanded");Check(doc.LabelBounds(0).X==12&&doc.LabelBounds(0).Y==9,"print margins");if(PrinterSettings.InstalledPrinters.Count>0){var pc=new PreviewPrintController();doc.PrintController=pc;doc.Print();var pages=pc.GetPreviewPageInfo();Check(pages.Length==1,"one preview page");using(var image=new Bitmap(900,550))using(var g=Graphics.FromImage(image)){g.Clear(Color.White);g.DrawImage(pages[0].Image,new Rectangle(0,0,900,550));image.Save(Path.Combine(dir,"windows-preview.png"));}foreach(var p in pages)p.Image.Dispose();}}
  for(int i=0;i<4;i++){((ComboBox)Field(f,"language")).SelectedIndex=i;Application.DoEvents();Snap(f,"main-"+i);}
  // Show paper tab through its actual tab button.
  ShowPaper(f);Snap(f,"paper-tab");f.Size=f.MinimumSize;Application.DoEvents();Snap(f,"minimum-size");Call(f,"Apply",LabelSettings.Default());f.Close();
 }}
 static bool ShowPaper(Control c){foreach(Control child in c.Controls){if(child is Button&&child.Text==Loc.T("Papier")){((Button)child).PerformClick();Application.DoEvents();return true;}if(ShowPaper(child))return true;}return false;}
}
